// 支出申请处理逻辑
const request = $input.first().json;

// 测试数据：模拟支出申请
const testExpenseRequests = [
  {
    applicant: "张三",
    amount: 3000,
    category: "办公用品",
    description: "采购办公文具",
    department: "行政部",
    requestDate: new Date().toISOString().split('T')[0]
  },
  {
    applicant: "李四",
    amount: 15000,
    category: "设备采购",
    description: "购买笔记本电脑",
    department: "技术部",
    requestDate: new Date().toISOString().split('T')[0]
  },
  {
    applicant: "王五",
    amount: 80000,
    category: "设备采购",
    description: "采购服务器设备",
    department: "技术部",
    requestDate: new Date().toISOString().split('T')[0]
  },
  {
    applicant: "赵六",
    amount: 5000,
    category: "差旅费",
    description: "商务出差费用",
    department: "销售部",
    requestDate: new Date().toISOString().split('T')[0]
  },
  {
    applicant: "钱七",
    amount: 120000,
    category: "设备采购",
    description: "采购生产设备",
    department: "生产部",
    requestDate: new Date().toISOString().split('T')[0]
  }
];

// 使用传入的请求数据或测试数据
const expenseRequest = request.applicant ? request : testExpenseRequests[0];

// 金额判断逻辑
const amount = expenseRequest.amount;
const threshold = 50000;
const isLargeAmount = amount >= threshold;
const requiresContract = amount >= threshold;
const approvalLevel = amount >= threshold ? 'high' : 'normal';

// 审批流程配置
let approvalFlow = [];
if (isLargeAmount) {
  approvalFlow = [
    { level: 1, approver: "部门负责人", status: "pending" },
    { level: 2, approver: "财务审核", status: "pending" },
    { level: 3, approver: "创始人终审", status: "pending" }
  ];
} else {
  approvalFlow = [
    { level: 1, approver: "部门负责人", status: "pending" },
    { level: 2, approver: "财务审核", status: "pending" }
  ];
}

// 合同检查要求
const contractCheck = {
  required: requiresContract,
  status: requiresContract ? "pending" : "not_required",
  contractAmount: requiresContract ? amount : null,
  contractType: requiresContract ? "采购合同" : null
};

return [{
  json: {
    requestId: `REQ_${Date.now()}`,
    applicant: expenseRequest.applicant,
    amount: expenseRequest.amount,
    category: expenseRequest.category,
    description: expenseRequest.description,
    department: expenseRequest.department,
    requestDate: expenseRequest.requestDate,
    isLargeAmount,
    requiresContract,
    approvalLevel,
    approvalFlow,
    contractCheck,
    status: "submitted",
    createdAt: new Date().toISOString()
  }
}];

// 小额支出审批流程
const request = $input.first().json;

// 模拟审批流程
const approvalSteps = [
  {
    step: 1,
    approver: "部门负责人",
    status: "approved",
    comment: "同意申请",
    approvedAt: new Date().toISOString()
  },
  {
    step: 2,
    approver: "财务审核",
    status: "approved",
    comment: "财务审核通过",
    approvedAt: new Date().toISOString()
  }
];

return [{
  json: {
    ...request,
    approvalSteps,
    finalStatus: "approved",
    approvedAt: new Date().toISOString(),
    approvalType: "normal"
  }
}];

// 大额支出审批流程
const request = $input.first().json;

// 模拟大额审批流程
const approvalSteps = [
  {
    step: 1,
    approver: "部门负责人",
    status: "approved",
    comment: "同意申请，已提交财务审核",
    approvedAt: new Date().toISOString()
  },
  {
    step: 2,
    approver: "财务审核",
    status: "approved",
    comment: "财务审核通过，已提交创始人终审",
    approvedAt: new Date().toISOString()
  },
  {
    step: 3,
    approver: "创始人终审",
    status: "approved",
    comment: "终审通过，可以执行采购",
    approvedAt: new Date().toISOString()
  }
];

return [{
  json: {
    ...request,
    approvalSteps,
    finalStatus: "approved",
    approvedAt: new Date().toISOString(),
    approvalType: "high"
  }
}];

// 合同检查逻辑
const request = $input.first().json;

// 模拟合同检查
const contractCheck = {
  required: request.contractCheck.required,
  status: request.contractCheck.required ? "verified" : "not_required",
  contractAmount: request.amount,
  contractType: "采购合同",
  contractNumber: request.contractCheck.required ? `CONTRACT_${Date.now()}` : null,
  verifiedAt: request.contractCheck.required ? new Date().toISOString() : null,
  verifiedBy: request.contractCheck.required ? "法务部门" : null
};

return [{
  json: {
    ...request,
    contractCheck,
    contractVerified: request.contractCheck.required ? true : true
  }
}];

// 审批完成通知
const request = $input.first().json;

const notification = {
  to: "founder@company.com",
  subject: `支出申请审批完成 - ${request.applicant}`,
  content: `
    申请人: ${request.applicant}
    金额: ¥${request.amount.toLocaleString()}
    类别: ${request.category}
    描述: ${request.description}
    审批状态: ${request.finalStatus}
    审批类型: ${request.approvalType}
    合同检查: ${request.contractVerified ? '已通过' : '未通过'}
    完成时间: ${request.approvedAt}
  `,
  priority: request.approvalType === 'high' ? 'high' : 'normal'
};

return [{
  json: {
    ...request,
    notification,
    completedAt: new Date().toISOString()
  }
}];

// 归档审批记录到Pinecone
const approvalData = $input.first().json;

// 构建审批记录文档
const approvalDocument = {
  id: approvalData.requestId,
  type: 'approval_record',
  applicant: approvalData.applicant,
  amount: approvalData.amount,
  category: approvalData.category,
  description: approvalData.description,
  department: approvalData.department,
  approvalLevel: approvalData.approvalLevel,
  approvalSteps: approvalData.approvalSteps,
  finalStatus: approvalData.finalStatus,
  contractCheck: approvalData.contractCheck,
  createdAt: approvalData.createdAt,
  completedAt: approvalData.completedAt,
  content: `
    审批记录ID: ${approvalData.requestId}
    申请人: ${approvalData.applicant}
    申请金额: ¥${approvalData.amount.toLocaleString()}
    申请类别: ${approvalData.category}
    申请描述: ${approvalData.description}
    所属部门: ${approvalData.department}
    审批级别: ${approvalData.approvalLevel}
    审批状态: ${approvalData.finalStatus}
    合同检查: ${approvalData.contractCheck.required ? '需要' : '不需要'}
    创建时间: ${approvalData.createdAt}
    完成时间: ${approvalData.completedAt}
  `
};

return [{
  json: approvalDocument,
  binary: {}
}];

// Generate test financial data
const testFinancialData = [
  {
    date: '2024-01-15',
    type: 'income',
    amount: 50000,
    category: 'Sales Revenue',
    description: 'Product sales revenue',
    source: 'Bank statement'
  },
  {
    date: '2024-01-15',
    type: 'expense',
    amount: 15000,
    category: 'Office Expenses',
    description: 'Office supplies purchase',
    source: 'Invoice'
  },
  {
    date: '2024-01-15',
    type: 'expense',
    amount: 8000,
    category: 'Personnel Cost',
    description: 'Employee salaries',
    source: 'Payroll'
  },
  {
    date: '2024-01-15',
    type: 'income',
    amount: 30000,
    category: 'Service Revenue',
    description: 'Technical service fee',
    source: 'Contract'
  },
  {
    date: '2024-01-15',
    type: 'expense',
    amount: 5000,
    category: 'Marketing Expenses',
    description: 'Advertising placement',
    source: 'Invoice'
  },
  {
    date: '2024-01-15',
    type: 'expense',
    amount: 12000,
    category: 'Equipment Purchase',
    description: 'Server equipment',
    source: 'Purchase contract'
  },
  {
    date: '2024-01-15',
    type: 'income',
    amount: 25000,
    category: 'Other Income',
    description: 'Investment returns',
    source: 'Bank statement'
  },
  {
    date: '2024-01-15',
    type: 'expense',
    amount: 3000,
    category: 'Travel Expenses',
    description: 'Business travel',
    source: 'Reimbursement'
  },
  {
    date: '2024-01-15',
    type: 'expense',
    amount: 2000,
    category: 'Tax',
    description: 'VAT',
    source: 'Tax filing'
  },
  {
    date: '2024-01-15',
    type: 'income',
    amount: 15000,
    category: 'Sales Revenue',
    description: 'Software license fee',
    source: 'Contract'
  }
];

// 计算财务汇总
const totalIncome = testFinancialData
  .filter(item => item.type === 'income')
  .reduce((sum, item) => sum + item.amount, 0);

const totalExpense = testFinancialData
  .filter(item => item.type === 'expense')
  .reduce((sum, item) => sum + item.amount, 0);

const netCashFlow = totalIncome - totalExpense;

// 按类别汇总
const categorySummary = {};
testFinancialData.forEach(item => {
  if (!categorySummary[item.category]) {
    categorySummary[item.category] = { income: 0, expense: 0 };
  }
  if (item.type === 'income') {
    categorySummary[item.category].income += item.amount;
  } else {
    categorySummary[item.category].expense += item.amount;
  }
});

return [{
  json: {
    date: new Date().toISOString().split('T')[0],
    totalIncome,
    totalExpense,
    netCashFlow,
    categorySummary,
    transactions: testFinancialData,
    reportType: 'daily'
  }
}];
